oto"],"tags":["media_art","installation","digital_image","production","project","team","portfolio"],"connectionText":"정적인 3D 모델을 사용자 반응이 가능한 실감형 콘텐츠로 확장한 이전 융복합 제작 경험","locations":"광주대학교","faculty":["윤태준"],"sourcePageTitle":"2024 스마트 드론 활용 3D데이터 및 전문인력양성 결과보고서","sourceUrl":null,"sourceCheckedAt":"2026-07-19","verificationNote":"참여 4명, 결과보고서 작성 시점에는 예정으로 표기. 2025년도 이전 경험으로 메인 노출 빈도 낮음","priority":3,"programGroup":"스마트 드론·3D 인력양성","displayTier":"experience","displayKind":"짧은경험","cancelled":false},{"key":"photo_next_2024_drone_lidar_orthophoto_lab","category":"이전경험","title":"드론 3D·지상 LiDAR 스캐닝 정사영상 제작","year":2024,"status":"완료","statusLabel":"이전 운영 경험","startDate":"2024-11-11","endDate":"2024-12-12","semester":null,"periodLabel":"2024년 11월 11일~12월 12일","summary":"드론 3D 스캐닝과 지상 LiDAR로 취득한 데이터를 결합해 정사영상과 공간 데이터를 제작한 프로젝트랩","activities":"드론 촬영, 지상 LiDAR 스캐닝, 데이터 정합과 정사영상 제작에 8명 참여","outcomes":"정사영상 및 3D 공간 데이터","primaryTrack":"video","secondaryTracks":["documentary"],"tags":["field","digital_image","camera","video","research","production","project","team"],"connectionText":"항공과 지상에서 취득한 데이터를 통합해 공간을 정밀하게 기록하는 학과의 고도화된 기술 경험","locations":"광주대학교 및 외부 스캐닝 현장","faculty":["윤태준"],"sourcePageTitle":"2024 스마트 드론 활용 3D데이터 및 전문인력양성 결과보고서","sourceUrl":null,"sourceCheckedAt":"2026-07-19","verificationNote":"참여 8명, 결과보고서 작성 시점에는 예정으로 표기. 2025년도 이전 경험으로 메인 노출 빈도 낮음","priority":3,"programGroup":"스마트 드론·3D 인력양성","displayTier":"experience","displayKind":"짧은경험","cancelled":false}]$project_catalog$::jsonb) item(value)
  loop
    if coalesce((v_item ->> 'cancelled')::boolean, false) then
      continue;
    end if;

    v_metadata := pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
      'seedKey', 'project_catalog:' || (v_item ->> 'key'),
      'catalogKey', v_item ->> 'key',
      'projectYear', (v_item ->> 'year')::integer,
      'displayTier', v_item ->> 'displayTier',
      'displayKind', v_item ->> 'displayKind',
      'periodLabel', v_item ->> 'periodLabel',
      'statusLabel', v_item ->> 'statusLabel',
      'programGroup', v_item ->> 'programGroup',
      'semester', v_item ->> 'semester',
      'category', v_item ->> 'category',
      'activities', v_item ->> 'activities',
      'outcomes', v_item ->> 'outcomes',
      'locations', v_item ->> 'locations',
      'faculty', v_item -> 'faculty',
      'sourcePageTitle', v_item ->> 'sourcePageTitle',
      'sourceUrl', v_item ->> 'sourceUrl',
      'sourceCheckedAt', v_item ->> 'sourceCheckedAt',
      'verificationNote', v_item ->> 'verificationNote'
    ));

    update public.resources
    set type = 'project',
        title = v_item ->> 'title',
        summary = v_item ->> 'summary',
        connection_template = coalesce(
          v_item ->> 'connectionText',
          '선택한 관심사를 학과 프로젝트 경험으로 연결합니다.'
        ),
        status = 'active',
        visibility = 'public',
        priority = (v_item ->> 'priority')::smallint,
        source_date = coalesce((v_item ->> 'sourceCheckedAt')::date, current_date),
        metadata = v_metadata,
        image_path = null,
        updated_at = pg_catalog.clock_timestamp()
    where metadata ->> 'seedKey' = 'project_catalog:' || (v_item ->> 'key')
    returning id into v_resource_id;

    if not found then
      insert into public.resources(
        type, title, summary, connection_template, status, visibility, priority,
        source_date, metadata, image_path
      ) values (
        'project',
        v_item ->> 'title',
        v_item ->> 'summary',
        coalesce(v_item ->> 'connectionText', '선택한 관심사를 학과 프로젝트 경험으로 연결합니다.'),
        'active',
        'public',
        (v_item ->> 'priority')::smallint,
        coalesce((v_item ->> 'sourceCheckedAt')::date, current_date),
        v_metadata,
        null
      ) returning id into v_resource_id;
    end if;

    delete from public.resource_tags where resource_id = v_resource_id;
    insert into public.resource_tags(resource_id, tag_key, weight, is_primary)
    select
      v_resource_id,
      tag_key,
      max(weight)::smallint,
      bool_or(is_primary)
    from (
      select v_item ->> 'primaryTrack' as tag_key, 3 as weight, true as is_primary
      union all
      select secondary.value, 2, false
      from pg_catalog.jsonb_array_elements_text(
        coalesce(v_item -> 'secondaryTracks', '[]'::jsonb)
      ) secondary(value)
      union all
      select interest.value, 2, false
      from pg_catalog.jsonb_array_elements_text(
        coalesce(v_item -> 'tags', '[]'::jsonb)
      ) interest(value)
    ) tags
    group by tag_key;
  end loop;
end;
